import{_ as a,c as s,o as r,ai as o}from"./chunks/framework.DMRKKuRm.js";const g=JSON.parse('{"title":"Responsabilidades","description":"","frontmatter":{},"headers":[],"relativePath":"Reglas/responsabilidades.md","filePath":"Reglas/responsabilidades.md"}'),i={name:"Reglas/responsabilidades.md"};function n(t,e,l,d,c,u){return r(),s("div",null,e[0]||(e[0]=[o('<h1 id="responsabilidades" tabindex="-1">Responsabilidades <a class="header-anchor" href="#responsabilidades" aria-label="Permalink to &quot;Responsabilidades&quot;">​</a></h1><p>Responsabilidades de los jugadores y del staff en SilkCraft Network.</p><h2 id="responsabilidades-de-los-jugadores" tabindex="-1">Responsabilidades de los Jugadores <a class="header-anchor" href="#responsabilidades-de-los-jugadores" aria-label="Permalink to &quot;Responsabilidades de los Jugadores&quot;">​</a></h2><h3 id="conducta" tabindex="-1">Conducta <a class="header-anchor" href="#conducta" aria-label="Permalink to &quot;Conducta&quot;">​</a></h3><ul><li><strong>Respetar a otros jugadores:</strong> Trata a todos con respeto y cortesía</li><li><strong>Seguir las reglas:</strong> Es tu responsabilidad conocer y seguir todas las reglas del servidor</li><li><strong>Reportar problemas:</strong> Si ves algo que va contra las reglas, repórtalo al staff</li><li><strong>Mantener tu cuenta segura:</strong> No compartas tu cuenta con otros</li></ul><h3 id="cuenta-y-seguridad" tabindex="-1">Cuenta y Seguridad <a class="header-anchor" href="#cuenta-y-seguridad" aria-label="Permalink to &quot;Cuenta y Seguridad&quot;">​</a></h3><ul><li><strong>Una cuenta por jugador:</strong> No uses múltiples cuentas</li><li><strong>Protege tu contraseña:</strong> No compartas tu contraseña con nadie</li><li><strong>Reporta accesos no autorizados:</strong> Si sospechas que alguien accedió a tu cuenta, repórtalo inmediatamente</li><li><strong>No evadas sanciones:</strong> No uses cuentas alternativas para evadir bans o mutes</li></ul><h3 id="construcciones" tabindex="-1">Construcciones <a class="header-anchor" href="#construcciones" aria-label="Permalink to &quot;Construcciones&quot;">​</a></h3><ul><li><strong>Protege tus builds:</strong> Usa <code>/claim</code> para proteger tus construcciones</li><li><strong>Respeta los claims:</strong> No construyas en áreas protegidas sin permiso</li><li><strong>Mantén el servidor limpio:</strong> No construyas estructuras que causen lag</li><li><strong>Reporta griefing:</strong> Si alguien destruye tu construcción, repórtalo con evidencia</li></ul><h3 id="comunicacion" tabindex="-1">Comunicación <a class="header-anchor" href="#comunicacion" aria-label="Permalink to &quot;Comunicación&quot;">​</a></h3><ul><li><strong>Usa el chat apropiadamente:</strong> Mantén el chat apropiado para todas las edades</li><li><strong>Respeta al staff:</strong> Las decisiones del staff son finales</li><li><strong>No spamees:</strong> No satures el chat con mensajes repetitivos</li><li><strong>Sé constructivo:</strong> Si tienes críticas, exprésalas de forma respetuosa</li></ul><h2 id="responsabilidades-del-staff" tabindex="-1">Responsabilidades del Staff <a class="header-anchor" href="#responsabilidades-del-staff" aria-label="Permalink to &quot;Responsabilidades del Staff&quot;">​</a></h2><h3 id="moderacion" tabindex="-1">Moderación <a class="header-anchor" href="#moderacion" aria-label="Permalink to &quot;Moderación&quot;">​</a></h3><ul><li><strong>Aplicar las reglas justamente:</strong> El staff debe aplicar las reglas de forma consistente y justa</li><li><strong>Mantener el orden:</strong> El staff debe mantener un ambiente positivo en el servidor</li><li><strong>Responder a reportes:</strong> El staff debe responder a reportes de forma oportuna</li><li><strong>Ser ejemplo:</strong> El staff debe ser un ejemplo de buena conducta</li></ul><h3 id="soporte" tabindex="-1">Soporte <a class="header-anchor" href="#soporte" aria-label="Permalink to &quot;Soporte&quot;">​</a></h3><ul><li><strong>Ayudar a jugadores:</strong> El staff debe ayudar a jugadores con problemas o preguntas</li><li><strong>Ser paciente:</strong> El staff debe ser paciente con jugadores nuevos</li><li><strong>Proporcionar información:</strong> El staff debe proporcionar información precisa sobre el servidor</li><li><strong>Mantener profesionalismo:</strong> El staff debe mantener profesionalismo en todo momento</li></ul><h3 id="transparencia" tabindex="-1">Transparencia <a class="header-anchor" href="#transparencia" aria-label="Permalink to &quot;Transparencia&quot;">​</a></h3><ul><li><strong>Comunicar decisiones:</strong> El staff debe comunicar claramente las decisiones importantes</li><li><strong>Ser accesible:</strong> El staff debe estar disponible para ayudar cuando sea posible</li><li><strong>Escuchar feedback:</strong> El staff debe escuchar el feedback de la comunidad</li><li><strong>Mantener confidencialidad:</strong> El staff debe mantener confidencialidad sobre asuntos internos</li></ul><h2 id="responsabilidades-del-servidor" tabindex="-1">Responsabilidades del Servidor <a class="header-anchor" href="#responsabilidades-del-servidor" aria-label="Permalink to &quot;Responsabilidades del Servidor&quot;">​</a></h2><h3 id="rendimiento" tabindex="-1">Rendimiento <a class="header-anchor" href="#rendimiento" aria-label="Permalink to &quot;Rendimiento&quot;">​</a></h3><ul><li><strong>Mantener el servidor estable:</strong> El servidor debe mantener un buen rendimiento</li><li><strong>Actualizaciones regulares:</strong> El servidor debe recibir actualizaciones y mejoras</li><li><strong>Backups regulares:</strong> El servidor debe tener backups regulares para proteger el progreso de los jugadores</li></ul><h3 id="seguridad" tabindex="-1">Seguridad <a class="header-anchor" href="#seguridad" aria-label="Permalink to &quot;Seguridad&quot;">​</a></h3><ul><li><strong>Protección contra hacks:</strong> El servidor debe tener sistemas anti-cheat efectivos</li><li><strong>Protección de datos:</strong> El servidor debe proteger los datos de los jugadores</li><li><strong>Seguridad del servidor:</strong> El servidor debe estar protegido contra ataques</li></ul><h3 id="comunicacion-1" tabindex="-1">Comunicación <a class="header-anchor" href="#comunicacion-1" aria-label="Permalink to &quot;Comunicación&quot;">​</a></h3><ul><li><strong>Anuncios claros:</strong> El servidor debe comunicar cambios importantes claramente</li><li><strong>Transparencia:</strong> El servidor debe ser transparente sobre políticas y decisiones</li><li><strong>Feedback:</strong> El servidor debe escuchar y considerar el feedback de la comunidad</li></ul><h2 id="resolucion-de-conflictos" tabindex="-1">Resolución de Conflictos <a class="header-anchor" href="#resolucion-de-conflictos" aria-label="Permalink to &quot;Resolución de Conflictos&quot;">​</a></h2><h3 id="si-tienes-un-problema" tabindex="-1">Si Tienes un Problema <a class="header-anchor" href="#si-tienes-un-problema" aria-label="Permalink to &quot;Si Tienes un Problema&quot;">​</a></h3><ol><li><strong>Intenta resolverlo tú mismo:</strong> Muchos problemas se pueden resolver hablando con la otra persona</li><li><strong>Contacta al staff:</strong> Si no puedes resolverlo, contacta a un miembro del staff</li><li><strong>Proporciona evidencia:</strong> Si es posible, proporciona evidencia (screenshots, videos, etc.)</li><li><strong>Sé paciente:</strong> El staff puede tardar en responder, especialmente si hay muchos reportes</li></ol><h3 id="proceso-de-apelacion" tabindex="-1">Proceso de Apelación <a class="header-anchor" href="#proceso-de-apelacion" aria-label="Permalink to &quot;Proceso de Apelación&quot;">​</a></h3><p>Si crees que fuiste sancionado injustamente:</p><ol><li>Únete a nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a></li><li>Ve al canal de apelaciones</li><li>Explica tu situación de forma clara y respetuosa</li><li>Proporciona evidencia si es necesario</li><li>Espera la respuesta del staff</li></ol><h2 id="preguntas-frecuentes" tabindex="-1">Preguntas Frecuentes <a class="header-anchor" href="#preguntas-frecuentes" aria-label="Permalink to &quot;Preguntas Frecuentes&quot;">​</a></h2><h3 id="¿que-hago-si-un-staff-es-abusivo" tabindex="-1">¿Qué hago si un staff es abusivo? <a class="header-anchor" href="#¿que-hago-si-un-staff-es-abusivo" aria-label="Permalink to &quot;¿Qué hago si un staff es abusivo?&quot;">​</a></h3><p>Reporta el comportamiento a un administrador en nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a> con evidencia.</p><h3 id="¿que-hago-si-mi-construccion-fue-destruida" tabindex="-1">¿Qué hago si mi construcción fue destruida? <a class="header-anchor" href="#¿que-hago-si-mi-construccion-fue-destruida" aria-label="Permalink to &quot;¿Qué hago si mi construcción fue destruida?&quot;">​</a></h3><p>Reporta el griefing al staff con evidencia (screenshots, coordenadas, etc.). El staff puede restaurar construcciones si es posible.</p><h3 id="¿que-hago-si-fui-hackeado" tabindex="-1">¿Qué hago si fui hackeado? <a class="header-anchor" href="#¿que-hago-si-fui-hackeado" aria-label="Permalink to &quot;¿Qué hago si fui hackeado?&quot;">​</a></h3><p>Contacta al staff inmediatamente. Pueden ayudarte a recuperar tu cuenta y proteger tus items.</p><h3 id="¿el-servidor-es-responsable-de-mis-items-perdidos" tabindex="-1">¿El servidor es responsable de mis items perdidos? <a class="header-anchor" href="#¿el-servidor-es-responsable-de-mis-items-perdidos" aria-label="Permalink to &quot;¿El servidor es responsable de mis items perdidos?&quot;">​</a></h3><p>El servidor hace backups regulares, pero no puede garantizar la recuperación de items perdidos por causas no relacionadas con el servidor.</p><hr><p><strong>Recuerda:</strong> Todos somos parte de esta comunidad. Trabajemos juntos para mantener un ambiente positivo y divertido para todos.</p><p>Para más información, consulta <a href="/Reglas/normativa-general.html">Normativa General</a> o contacta al staff en nuestro <a href="https://discord.silkcraft.net" target="_blank" rel="noreferrer">Discord</a>.</p>',43)]))}const h=a(i,[["render",n]]);export{g as __pageData,h as default};
